CREATE COLUMN TABLE "TEST_AP"."OPRT" ("PrtId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(15) NOT NULL , "RelatnType" NVARCHAR(20), "RelatCard" NVARCHAR(15), "Memo" NVARCHAR(50), "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "DefaultORL" INTEGER CS_INT, PRIMARY KEY ("PrtId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPRT_NAME" ON "TEST_AP"."OPRT" ( "Name" ASC )